CREATE TABLE Posts (
    post_id varchar(10) PRIMARY KEY,
    account_id varchar(10),
    post_type VARCHAR(30),
    caption VARCHAR(500),
    posted_at DATETIME,
    likes_count INT ,
    comments_count INT ,
    shares_count INT ,
    FOREIGN KEY (account_id) REFERENCES UserAccount(account_id)
);

