-- 1. selecting all the records from all the table --
 
SELECT * FROM Users;
SELECT * FROM Platforms;
SELECT * FROM UserAccount;
SELECT * FROM Posts;
SELECT * FROM PostMetric;
SELECT * FROM Comments;
SELECT * FROM Likes;
SELECT * FROM Follows;
SELECT * FROM Hashtags;
SELECT * FROM PostHashtag;
SELECT * FROM Campaigns;
SELECT * FROM AdPerformance;

-- 2.counting the total rows from all the table ---

SELECT 'Users' AS table_name, COUNT(*) AS total_rows FROM Users
UNION ALL
SELECT 'Platforms', COUNT(*) FROM Platforms
UNION ALL
SELECT 'UserAccount', COUNT(*) FROM UserAccount
UNION ALL
SELECT 'Posts', COUNT(*) FROM Posts
UNION ALL
SELECT 'PostMetric', COUNT(*) FROM PostMetric
UNION ALL
SELECT 'Comments', COUNT(*) FROM Comments
UNION ALL
SELECT 'Likes', COUNT(*) FROM Likes
UNION ALL
SELECT 'Follows', COUNT(*) FROM Follows
UNION ALL
SELECT 'Hashtags', COUNT(*) FROM Hashtags
UNION ALL
SELECT 'PostHashtag', COUNT(*) FROM PostHashtag
UNION ALL
SELECT 'Campaigns', COUNT(*) FROM Campaigns
UNION ALL
SELECT 'AdPerformance', COUNT(*) FROM AdPerformance;

-- 3.selecting the particular records--

select* from campaigns where platform_id=1;

select user_name,full_name,city from users where city='coimbatore';

   -- arthimetic function--

SELECT
    COUNT(*) AS total_posts,
    SUM(likes_count) AS total_likes,
    SUM(shares_count) AS total_shares,
    AVG(likes_count) AS average_likes,
    MAX(likes_count) AS highest_likes,
    MIN(likes_count) AS lowest_likes
FROM Posts;

-- 4.joins--- 

select
u.user_id,
u.user_name,
u.full_name,
p.platform_id,
p.platform_name,
a.followers_count
from users  as u
inner join useraccount as a on u.user_id=a.user_id
inner join platforms p on a.platform_id=p.platform_id;
use social_media;

-- 5.select the record using the condition --

SELECT 
    post_id,
    caption,
    likes_count
FROM Posts
where likes_count>80000;


-- 6.count and display total users using the platform--
SELECT
    p.platform_name,
    COUNT(DISTINCT a.user_id) AS total_users
FROM Platforms p
LEFT JOIN UserAccount a
    ON p.platform_id = a.platform_id
GROUP BY p.platform_id, p.platform_name
ORDER BY total_users DESC;

-- 7.count and display total no. of post using the hashtags--

SELECT
    h.hashtag_name,
    COUNT(ph.post_id) AS total_posts
FROM Hashtags h
LEFT JOIN PostHashtag ph
    ON h.hashtag_id = ph.hashtag_id
GROUP BY h.hashtag_id, h.hashtag_name
ORDER BY total_posts DESC;


SELECT
    c.campaign_name,
    SUM(a.spend) AS total_spend,
    SUM(a.revenue) AS total_revenue,
    CAST(
        SUM(a.revenue) /
        NULLIF(SUM(a.spend), 0)
        AS DECIMAL(10,2)
    ) AS roas
FROM Campaigns c
JOIN AdPerformance a
    ON c.campaign_id = a.campaign_id
GROUP BY c.campaign_id, c.campaign_name
ORDER BY roas DESC;

-- 8.window function--

SELECT
    handle,
    followers_count,
    RANK() OVER (
        ORDER BY followers_count DESC
    ) AS follower_rank
FROM UserAccount;

-- 9.rank user with each platform --

SELECT
    p.platform_name,
    a.handle,
    a.followers_count,
    RANK() OVER (
        PARTITION BY p.platform_name
        ORDER BY a.followers_count DESC
    ) AS platform_rank
FROM UserAccount a
JOIN Platforms p
    ON a.platform_id = p.platform_id;
    
    -- 10.top 3 user from each platform --
    
    WITH RankedUsers AS (
    SELECT
        p.platform_name,
        a.handle,
        a.followers_count,
        ROW_NUMBER() OVER (
            PARTITION BY p.platform_name
            ORDER BY a.followers_count DESC
        ) AS rn
    FROM UserAccount a
    JOIN Platforms p
        ON a.platform_id = p.platform_id
)
SELECT *
FROM RankedUsers
WHERE rn <= 3;

-- 11.running total of followers--

SELECT
    account_id,
    handle,
    followers_count,
    SUM(followers_count) OVER (
        ORDER BY followers_count
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS running_followers
FROM UserAccount;

-- 12.Compare each user's followers with platform average--

SELECT
    p.platform_name,
    a.handle,
    a.followers_count,
    ROUND(
        AVG(a.followers_count) OVER (
            PARTITION BY a.platform_id
        ), 2
    ) AS platform_avg_followers,
    a.followers_count -
    AVG(a.followers_count) OVER (
        PARTITION BY a.platform_id
    ) AS difference_from_average
FROM UserAccount a
JOIN Platforms p
    ON a.platform_id = p.platform_id;
    
    
-- 13.find using followers more than 100000 followers --

WITH HighFollowers AS (
    SELECT
        account_id,
        handle,
        followers_count
    FROM UserAccount
    WHERE followers_count > 100000
)
SELECT *
FROM HighFollowers
ORDER BY followers_count DESC;

-- 14.CTE + Aggregate func--
-- average follower grater than 50000--

WITH PlatformStats AS (
    SELECT
        platform_id,
        COUNT(*) AS total_accounts,
        SUM(followers_count) AS total_followers,
        AVG(followers_count) AS avg_followers
    FROM UserAccount
    GROUP BY platform_id
)
SELECT
    p.platform_name,
    ps.total_accounts,
    ps.total_followers,
    ROUND(ps.avg_followers, 2) AS avg_followers
FROM PlatformStats ps
JOIN Platforms p
    ON ps.platform_id = p.platform_id
WHERE ps.avg_followers > 50000;


-- 15.top 5 post by likes --

WITH RankedPosts AS (
    SELECT
        post_id,
        caption,
        likes_count,
        shares_count,
        ROW_NUMBER() OVER (
            ORDER BY likes_count DESC
        ) AS rn
    FROM Posts
)
SELECT
    post_id,
    caption,
    likes_count,
    shares_count
FROM RankedPosts
WHERE rn <= 5;

-- 16.top post for every account--

WITH RankedPosts AS (
    SELECT
        account_id,
        post_id,
        caption,
        likes_count,
        ROW_NUMBER() OVER (
            PARTITION BY account_id
            ORDER BY likes_count DESC
        ) AS rn
    FROM Posts
)
SELECT
    account_id,
    post_id,
    caption,
    likes_count
FROM RankedPosts
WHERE rn = 1;

-- 17.Campaign ROI / ROAS--

SELECT
    c.campaign_id,
    c.campaign_name,
    c.budget,
    SUM(a.spend) AS total_spend,
    SUM(a.revenue) AS total_revenue,

    ROUND(
        SUM(a.revenue) / NULLIF(SUM(a.spend), 0),
        2
    ) AS ROAS,

    ROUND(
        (SUM(a.revenue) - SUM(a.spend))
        / NULLIF(SUM(a.spend), 0) * 100,
        2
    ) AS ROI_percent

FROM Campaigns c
JOIN AdPerformance a
    ON c.campaign_id = a.campaign_id

GROUP BY
    c.campaign_id,
    c.campaign_name,
    c.budget
ORDER BY ROAS DESC;

-- 18.Campaign CTR and conversion rate--

SELECT
    c.campaign_name,

    SUM(a.impressions) AS impressions,
    SUM(a.clicks) AS clicks,
    SUM(a.conversions) AS conversions,

    ROUND(
        SUM(a.clicks) / NULLIF(SUM(a.impressions), 0) * 100,
        2
    ) AS CTR_percent,

    ROUND(
        SUM(a.conversions) / NULLIF(SUM(a.clicks), 0) * 100,
        2
    ) AS conversion_rate

FROM Campaigns c
JOIN AdPerformance a
    ON c.campaign_id = a.campaign_id

GROUP BY c.campaign_id, c.campaign_name;

-- 19.Advanced CTE + Aggregate + Window--
-- Rank campaigns by ROAS--

WITH CampaignStats AS (
    SELECT
        c.campaign_id,
        c.campaign_name,

        SUM(a.spend) AS total_spend,
        SUM(a.revenue) AS total_revenue,

        SUM(a.revenue) /
        NULLIF(SUM(a.spend), 0) AS roas

    FROM Campaigns c
    JOIN AdPerformance a
        ON c.campaign_id = a.campaign_id

    GROUP BY
        c.campaign_id,
        c.campaign_name
),

RankedCampaigns AS (
    SELECT
        *,
        RANK() OVER (
            ORDER BY roas DESC
        ) AS campaign_rank
    FROM CampaignStats
)

SELECT *
FROM RankedCampaigns
ORDER BY campaign_rank asc;

-- 20.Platform → Users → Followers → Rank--

WITH PlatformUsers AS (
    SELECT
        p.platform_name,
        a.handle,
        a.followers_count
    FROM Platforms p
    JOIN UserAccount a
        ON p.platform_id = a.platform_id
),

RankedUsers AS (
    SELECT
        platform_name,
        handle,
        followers_count,

        RANK() OVER (
            PARTITION BY platform_name
            ORDER BY followers_count DESC
        ) AS platform_rank,

        AVG(followers_count) OVER (
            PARTITION BY platform_name
        ) AS platform_average

    FROM PlatformUsers
)

SELECT
    platform_name,
    handle,
    followers_count,
    platform_rank,
    ROUND(platform_average, 2) AS platform_average,

    ROUND(
        followers_count - platform_average,
        2
    ) AS difference_from_average

FROM RankedUsers
WHERE platform_rank <= 5
ORDER BY platform_name, platform_rank;





































